    long long dist;
    int u;
    int cost;
} HeapNode;

static Edge edges[4005];
static int head[10005];
static int edge_cnt = 0;

static void add_edge(int u, int v, int t, int c) {
    edges[edge_cnt].to = v;
    edges[edge_cnt].time = t;
    edges[edge_cnt].cost = c;
    edges[edge_cnt].next = head[u];
    head[u] = edge_cnt++;
}

