static int heap_size = 0;

static void push(long long dist, int u, int cost) {
    int i = ++heap_size;
    while (i > 1) {
        int p = i / 2;
        if (heap[p].dist <= dist) break;
        heap[i] = heap[p];
        i = p;
    }
    heap[i].dist = dist;
    heap[i].u = u;
    heap[i].cost = cost;
}

static HeapNode pop(void) {
    HeapNode min_node = heap[1];
    HeapNode last = heap[heap_size--];
    if (heap_size == 0) return min_node;

    int i = 1;
    while (i * 2 <= heap_size) {
        int child = i * 2;
        if (child + 1 <= heap_size && heap[child + 1].dist < heap[child].dist) {
            child++;
        }
        if (last.dist <= heap[child].dist) break;
        heap[i] = heap[child];
        i = child;
    }
    heap[i] = last;
    return min_node;
}

static int min_cost[10005];

int main(void) {
    int v_max, n, m;
    if (scanf("%d %d %d", &v_max, &n, &m) != 3) return 0;

    for (int i = 1; i <= n; i++) {
        head[i] = -1;
        min_cost[i] = v_max + 1;
    }

    for (int i = 0; i < m; i++) {
        int a, b, t, p;
        scanf("%d %d %d %d", &a, &b, &t, &p);
        add_edge(a, b, t, p);
        add_edge(b, a, t, p);
    }

    int start, end;
    scanf("%d %d", &start, &end);

    if (start == end) {
        printf("0\n");
        return 0;
    }

    push(0, start, 0);

    long long ans = -1;

    while (heap_size > 0) {
        HeapNode cur = pop();
        int u = cur.u;
        int c = cur.cost;
        long long d = cur.dist;

        if (c >= min_cost[u]) continue;
        min_cost[u] = c;

        if (u == end) {
            ans = d;
            break;
        }

        for (int e = head[u]; e != -1; e = edges[e].next) {
            int v = edges[e].to;
            int nc = c + edges[e].cost;
            if (nc <= v_max && nc < min_cost[v]) {
                push(d + edges[e].time, v, nc);
            }
        }
    }

    printf("%lld\n", ans);
    return 0;
}
